insert into public.categories (id, name, slug, description, image_url, sort_order, is_active) values
  ('d3bc9f0c-30a2-502a-9e11-a16debc6a1c2', 'Border bangles', 'border-bangles', 'Intricately detailed bangles that frame the wrist — kundan, coin, lotus and crystal work.', '/images/products/bng-175-golden-square-kundan-bangles.jpg', 0, true),
