  ('5336f3f5-70c1-5116-b1f9-6cf6eb2a5241', 'Centre clips', 'centre-clips', 'Crystal and floral centre clips to finish a braided or bunned hairstyle.', '/images/products/bng-169-rectangle-crystal-lavender.jpg', 5, true),
  ('40e637f9-0c6e-5df3-97b1-bd5a1d8cff29', 'Brooch pins', 'brooch-pins', 'Small brooch pins in leaf, star, coin and crystal motifs.', '/images/products/bng-149-red-leaf-brooch-pin.jpg', 6, true),
  ('47f069e4-bb01-579f-b16c-701f9f150b40', 'Jada pillai', 'jada-pillai', 'Jada pillai chains and hair hooks with coin, lotus and pearl detailing.', '/images/products/bng-151-laksmi-with-coin-hair-hook.jpg', 7, true),
  ('0ab6ca75-2da5-5da9-899d-4a6b3b66c4c5', 'Jasmine clip', 'jasmine-clip', 'Jasmine hair accessories and combos for traditional hairstyling.', '/images/products/bng-150-jasmine-hair-accessories-combo.jpg', 8, true),
